[package]
name = "myapp"
version = "0.1.0"
edition = "2024"

[dependencies]
charpente = "0.1"
serde = { version = "1", features = ["derive"] }

[dev-dependencies]
charpente-sim = "0.1"

[[test]]
name = "sim"
